INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300019, now(), now(), 'seed', '<h2>Privacy policy</h2><p>USA Electronics Hub, 456 Tech Avenue, New York, NY 10001, decides how your data is used.</p><h3>What we collect</h3><ul><li>Account and delivery details</li><li>Order, repair and trade-in history</li><li>Device serial numbers, which is how a warranty claim is verified</li></ul><h3>How long we keep it</h3><p>Order records are kept seven years for tax purposes; account data three years after your last activity; repair records for the life of the warranty plus one year.</p><h3>Your choices</h3><p>California residents may request access, deletion and opt-out of sale under the CCPA — we do not sell personal information. Write to <a href="mailto:privacy@usaelectronics.com">privacy@usaelectronics.com</a>.</p>', 'Privacy policy', 'Privacy policy', null, null, null, null, 'en', -30010, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300020, now(), now(), 'seed', '<h2>Politique de confidentialité</h2><p>USA Electronics Hub, 456 Tech Avenue, New York, NY 10001, décide de l''usage fait de vos données.</p><h3>Données collectées</h3><ul><li>Compte et coordonnées de livraison</li><li>Historique de commandes, réparations et reprises</li><li>Numéros de série des appareils, base de la vérification de garantie</li></ul><h3>Conservation</h3><p>Les commandes sont conservées sept ans à des fins fiscales, les données de compte trois ans après la dernière activité, les dossiers de réparation pendant la durée de garantie plus un an.</p><h3>Vos choix</h3><p>Les résidents de Californie disposent d''un droit d''accès, de suppression et d''opposition à la vente au titre du CCPA — nous ne vendons aucune donnée personnelle. Écrivez à <a href="mailto:privacy@usaelectronics.com">privacy@usaelectronics.com</a>.</p>', 'Politique de confidentialité', 'Politique de confidentialité', null, null, null, null, 'fr', -30010, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.policy_version (id, store_merchant_id, content_id, version, status, effective_from, note, translations, published_at, published_by)
VALUES (-3001, '65f023632bc46470c104b75f', -30010, 1, 'LIVE', now() - interval '30 days', null, '[{"language": "en", "title": "Privacy policy", "body": "<h2>Privacy policy</h2><p>USA Electronics Hub, 456 Tech Avenue, New York, NY 10001, decides how your data is used.</p><h3>What we collect</h3><ul><li>Account and delivery details</li><li>Order, repair and trade-in history</li><li>Device serial numbers, which is how a warranty claim is verified</li></ul><h3>How long we keep it</h3><p>Order records are kept seven years for tax purposes; account data three years after your last activity; repair records for the life of the warranty plus one year.</p><h3>Your choices</h3><p>California residents may request access, deletion and opt-out of sale under the CCPA — we do not sell personal information. Write to <a href=\"mailto:privacy@usaelectronics.com\">privacy@usaelectronics.com</a>.</p>", "state": "TRANSLATED"}, {"language": "fr", "title": "Politique de confidentialité", "body": "<h2>Politique de confidentialité</h2><p>USA Electronics Hub, 456 Tech Avenue, New York, NY 10001, décide de l''usage fait de vos données.</p><h3>Données collectées</h3><ul><li>Compte et coordonnées de livraison</li><li>Historique de commandes, réparations et reprises</li><li>Numéros de série des appareils, base de la vérification de garantie</li></ul><h3>Conservation</h3><p>Les commandes sont conservées sept ans à des fins fiscales, les données de compte trois ans après la dernière activité, les dossiers de réparation pendant la durée de garantie plus un an.</p><h3>Vos choix</h3><p>Les résidents de Californie disposent d''un droit d''accès, de suppression et d''opposition à la vente au titre du CCPA — nous ne vendons aucune donnée personnelle. Écrivez à <a href=\"mailto:privacy@usaelectronics.com\">privacy@usaelectronics.com</a>.</p>", "state": "TRANSLATED"}]', now(), 'seed')
on conflict (id) do nothing;

