INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300021, now(), now(), 'seed', '<h2>Return policy</h2><p>Forty-five days on anything unopened, thirty days on anything opened, counted from delivery.</p><h3>Conditions</h3><ul><li>All original accessories and packaging</li><li>Device signed out of its manufacturer account</li><li>Return shipping is free; we do not charge restocking fees</li></ul><h3>Refunds</h3><p>Issued within three business days of the item reaching our warehouse, to the original payment method.</p><p><em>Version 2 — the unopened window went from thirty to forty-five days, and the restocking fee is gone.</em></p>', 'Return policy', 'Return policy', null, null, null, null, 'en', -30011, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300022, now(), now(), 'seed', '<h2>Politique de retour</h2><p>Quarante-cinq jours sur tout produit non ouvert, trente jours sur un produit ouvert, à compter de la livraison.</p><h3>Conditions</h3><ul><li>Tous les accessoires et l''emballage d''origine</li><li>Appareil déconnecté du compte constructeur</li><li>Retour gratuit ; aucun frais de remise en stock</li></ul><h3>Remboursement</h3><p>Sous trois jours ouvrés après réception à l''entrepôt, sur le moyen de paiement d''origine.</p><p><em>Version 2 — la fenêtre non ouverte passe de trente à quarante-cinq jours, et les frais de remise en stock disparaissent.</em></p>', 'Politique de retour', 'Politique de retour', null, null, null, null, 'fr', -30011, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.policy_version (id, store_merchant_id, content_id, version, status, effective_from, note, translations, published_at, published_by)
