INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300023, now(), now(), 'seed', '<h2>Shipping policy</h2><p>Orders confirmed before 3pm Eastern ship the same business day from our Secaucus warehouse.</p><table><tr><th>Service</th><th>Time</th><th>Cost</th></tr><tr><td>Standard (contiguous US)</td><td>3–5 business days</td><td>Free over $75</td></tr><tr><td>Two-day</td><td>2 business days</td><td>$14.99</td></tr><tr><td>Overnight</td><td>Next business day</td><td>$29.99</td></tr><tr><td>Alaska, Hawaii, PR</td><td>5–8 business days</td><td>$24.99</td></tr></table><p>Anything over $500 ships with signature required. We do not deliver to freight forwarders.</p>', 'Shipping policy', 'Shipping policy', null, null, null, null, 'en', -30012, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300024, now(), now(), 'seed', '<h2>Conditions de livraison</h2><p>Les commandes confirmées avant 15h heure de l''Est partent le jour même de notre entrepôt de Secaucus.</p><table><tr><th>Service</th><th>Délai</th><th>Tarif</th></tr><tr><td>Standard (États contigus)</td><td>3–5 jours ouvrés</td><td>Offert dès 75 $</td></tr><tr><td>Deux jours</td><td>2 jours ouvrés</td><td>14,99 $</td></tr><tr><td>Lendemain</td><td>Jour ouvré suivant</td><td>29,99 $</td></tr><tr><td>Alaska, Hawaï, Porto Rico</td><td>5–8 jours ouvrés</td><td>24,99 $</td></tr></table><p>Toute commande au-delà de 500 $ exige une signature. Nous ne livrons pas les transitaires.</p>', 'Conditions de livraison', 'Conditions de livraison', null, null, null, null, 'fr', -30012, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.policy_version (id, store_merchant_id, content_id, version, status, effective_from, note, translations, published_at, published_by)
