INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300025, now(), now(), 'seed', '<h2>Cookies</h2><p>Three families of cookies, one of which you cannot turn off because the cart depends on it.</p><ul><li><strong>Essential</strong> — cart, session, fraud prevention. Always on.</li><li><strong>Analytics</strong> — aggregate traffic measurement, 13 months.</li><li><strong>Advertising</strong> — retargeting, 90 days, off by default.</li></ul><p>Your choice is stored for six months and can be changed from the “Cookie preferences” link in the footer at any time.</p>', 'Cookie policy', 'Cookie policy', null, null, null, null, 'en', -30013, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
INSERT INTO content.content_description (description_id, date_created, date_modified, updt_id, description, name, title, meta_description, meta_keywords, meta_title, sef_url, language_code, content_id, state, excerpt, alt_text, cta_label, subtitle)
VALUES (-300026, now(), now(), 'seed', '<h2>Cookies</h2><p>Trois familles de cookies, dont une que vous ne pouvez pas désactiver, le panier en dépendant.</p><ul><li><strong>Essentiels</strong> — panier, session, prévention de la fraude. Toujours actifs.</li><li><strong>Mesure</strong> — trafic agrégé, 13 mois.</li><li><strong>Publicité</strong> — reciblage, 90 jours, désactivé par défaut.</li></ul><p>Votre choix est conservé six mois et modifiable à tout moment depuis « Préférences cookies » en pied de page.</p>', 'Politique relative aux cookies', 'Politique relative aux cookies', null, null, null, null, 'fr', -30013, 'TRANSLATED', null, null, null, null)
on conflict (description_id) do nothing;
